class Solution {
  public int numWays(int n, int k) {
    if (n == 1) return k;
    // same: last two posts share a color; diff: they differ
    int same = k, diff = k * (k - 1);
    for (int i = 3; i <= n; i++) {
      int nextDiff = (same + diff) * (k - 1);
      same = diff;
      diff = nextDiff;
    }
    return same + diff;
  }
}
